const SCEN_FR_SURG = {
  tube_desat: { title: 'Désaturation chez un patient intubé (sonde trop enfoncée)', summary: "Femme de 64 ans (160 cm, 70 kg), intubée aux urgences il y a 20 min puis transférée sur le lit. Depuis le transfert la SpO2 baisse et l'hémithorax gauche se soulève à peine. Trouvez la cause au fibroscope et corrigez-la.", learning: ["Patient ventilé qui désature : DOPE - Déplacement (œsophage, trop profond, trop haut), Obstruction (sécrétions, coudure), Pneumothorax, Équipement. D'abord FiO2 1,0, puis regarder.", "Une sonde trop enfoncée passe dans la bronche souche droite : l'hémithorax gauche bouge à peine et la SpO2 chute. Le fibroscope montre l'absence de carène ou l'orifice du lobe supérieur droit au bout de la sonde.", "Retirer la sonde jusqu'à placer l'extrémité 2 à 6 cm au-dessus de la carène (repère optimal aux dents ≈ 0,1 x taille + 4 cm) et noter le nouveau repère.", "Aspirer les sécrétions par le fibroscope, faire des passages courts et garder une FiO2 élevée pendant que le fibroscope est dans la sonde."] },
  tension_ptx: { title: 'Pneumothorax sous tension chez un polytraumatisé ventilé', summary: "Homme de 31 ans (183 cm, 88 kg), traumatisé thoracique, intubé et ventilé en pression positive. La pression des voies aériennes monte, la PA et la SpO2 chutent. Examinez, décomprimez du bon côté avec un cathéter assez long, puis drainez.", learning: ["Patient traumatisé ventilé, pression des voies aériennes en hausse, PA et SpO2 en baisse : pensez d'abord au pneumothorax sous tension, n'attendez pas la radiographie.", "Décomprimez du côté du murmure aboli : cathéter long (7-8 cm) au 5e espace intercostal axillaire antérieur/moyen, ou au 2e espace médio-claviculaire. L'épaisseur de la paroi augmente avec l'IMC et un cathéter de 5 cm échoue chez environ un adulte sur trois.", "L'aiguille n'est qu'un relais : faites suivre d'un drain thoracique de gros calibre. Un cathéter bouché laisse la tension revenir.", "Une tension à droite compromet la circulation plus tôt qu'une tension à gauche."] },
  cico: { title: "Intubation et oxygénation impossibles (IMC 36)", summary: "Femme de 56 ans (165 cm, 98 kg) pour laparotomie urgente, tout juste induite et curarisée. La laryngoscopie va échouer, le masque et le dispositif supraglottique ne ventilent pas, la SpO2 chute. Déclarez-le et réalisez un abord du cou en urgence.", learning: ["Plan A-B-C-D (DAS 2015) : trois laryngoscopies au maximum, un seul dispositif supraglottique, optimiser le masque, puis déclarer la CICO et passer au cou - ne pas s'acharner sur la bouche pendant que la SpO2 baisse.", "Bistouri-bougie-sonde : ponction transversale de la membrane cricothyroïdienne, rotation de la lame, glisser la bougie, sonde à ballonnet de 6,0. Repères non palpables : incision verticale médiane de 8-10 cm, dissection mousse, puis la membrane.", "La palpation retrouve la membrane chez seulement 4 femmes obèses sur 10 : repérez-la à l'échographie avant l'induction si vous attendez une voie aérienne difficile.", "Une canule étroite exige une source haute pression et une voie d'expiration ; avec une obstruction haute complète elle expose au barotraumatisme (pneumothorax sous tension)."] },
};
