export function t(key, vars) {
  const dict = lang === 'fr' ? FR : EN;
  let v = dict[key] ?? EN[key] ?? key;
  if (typeof v === 'string' && vars) v = v.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? vars[k] : ''));
  return v;
}
export const drugName = (k, fallback) => (lang === 'fr' ? DRUG_FR[k] : null) || fallback || k;
// The 19 later cases in French (title, summary, objectives)
Object.assign(SCEN_FR, {
  anaphylaxis: { title: "Anaphylaxie à l'induction", summary: "Femme de 38 ans (165 cm, 64 kg), tout juste induite et intubée pour une cœlioscopie. Une minute après l'antibiotique et le curare, la pression chute, la pression des voies aériennes monte et le thorax rougit. Reconnaissez-la et traitez-la.", learning: ["Anaphylaxie peranesthésique : hypotension brutale, pression des voies aériennes élevée (bronchospasme), rougeur ou aucun signe cutané. Curares et antibiotiques sont les causes habituelles (NAP6).", "L'adrénaline est le traitement : 0,5 mg IM ou, sous anesthésie, bolus IV de 50 µg titrés selon l'effet, puis une perfusion si cela récidive.", "Remplissez vite : les capillaires fuient et le patient est vide.", "Antihistaminiques et corticoïdes ne font plus partie du traitement d'urgence."] },
  mh_crisis: { title: 'Hyperthermie maligne', summary: "Homme de 24 ans (180 cm, 78 kg), intubé avec succinylcholine et entretenu au sévoflurane pour une appendicectomie. Au bout de vingt minutes, l'EtCO2 monte malgré l'augmentation de la ventilation et il devient tachycarde. Trouvez la cause et traitez-la.", learning: ["Le signe le plus précoce est une hausse inexpliquée de l'EtCO2 malgré l'augmentation de la ventilation, avec une tachycardie ; la température monte plus tard.", "Arrêtez l'halogéné, hyperventilez en oxygène pur, appelez à l'aide et donnez du dantrolène 2,5 mg/kg, à répéter toutes les 10 min jusqu'à contrôle.", "Refroidissez activement, traitez l'hyperkaliémie et surveillez les troubles du rythme et la rhabdomyolyse."] },
  last_block: { title: "Toxicité des anesthésiques locaux après un bloc nerveux", summary: "Femme de 70 ans (158 cm, 55 kg), bloc fémoral à la bupivacaïne pour une fracture de hanche. Peu après l'injection, elle devient confuse et ne répond plus. Traitez ce qui se passe.", learning: ["Confusion, convulsions puis troubles du rythme et collapsus peu après un anesthésique local : pensez à la toxicité systémique (LAST).", "Arrêtez l'injection, appelez à l'aide, oxygénez, traitez les convulsions et donnez l'émulsion lipidique à 20 % : 1,5 mL/kg en 2-3 min puis 0,25 mL/kg/min.", "En arrêt cardiaque, doses d'adrénaline réduites (< 1 µg/kg), pas de vasopressine, et poursuivez la RCP : la récupération peut être longue."] },
  heart_block: { title: 'Bloc auriculo-ventriculaire complet avec choc', summary: "Homme de 78 ans (172 cm, 74 kg), hypertendu et diabétique de type 2, a des malaises toute la journée et il est maintenant gris et somnolent. Le scope montre un rythme très lent. Stabilisez-le.", learning: ["Une bradycardie avec choc, syncope, ischémie ou insuffisance cardiaque se traite tout de suite : atropine 500 µg (jusqu'à 3 mg), puis entraînement électrosystolique ou perfusion d'adrénaline/isoprénaline.", "L'atropine marche rarement dans un bloc complet sous-nodal : passez tôt à l'entraînement électrosystolique.", "Entraînement transcutané : électrodes, mode sentinelle, fréquence 60-70, augmentez l'intensité jusqu'à ce que chaque spike donne un QRS ET un pouls. C'est douloureux : analgésie et sédation."] },
  torsades: { title: 'Torsades de pointes', summary: "Femme de 66 ans (162 cm, 60 kg) sous sotalol pour une fibrillation atriale et traitée pour une hypertension, diarrhée depuis trois jours. Elle est scopée aux urgences avec un pouls lent quand elle perd brutalement connaissance. Reconnaissez le rythme, traitez-le et empêchez la récidive.", learning: ["La torsade de pointes est une TV polymorphe dont l'axe des QRS tourne autour de la ligne de base, sur un QT long. Sans pouls ou prolongée : défibrillez.", "Donnez 2 g de sulfate de magnésium IV même si la magnésémie est normale ; il prévient les récidives sans raccourcir le QT.", "Corrigez la kaliémie (viser 4,5-5), arrêtez tout médicament qui allonge le QT (ici le sotalol) et évitez l'amiodarone.", "Récidives après des pauses : accélérez la fréquence par isoprénaline ou entraînement électrosystolique."] },
  dka: { title: 'Acidocétose diabétique', summary: "Femme de 22 ans (165 cm, 55 kg), diabétique de type 1, vomit depuis deux jours et a arrêté son insuline faute de manger. Elle est somnolente, respire profondément et elle est déshydratée. Confirmez le diagnostic et conduisez les quatre premières heures du traitement.", learning: ["Acidocétose : cétonémie >= 3 mmol/L (ou cétonurie 2+), glycémie > 11 mmol/L ou diabète connu, et HCO3 < 15 ou pH < 7,3.", "Le remplissage d'abord (NaCl 0,9 % 1 L la première heure), puis insuline IV à débit fixe 0,1 U/kg/h, sans bolus.", "L'insuline et la correction de l'acidose font entrer le potassium dans les cellules : ajoutez 40 mmol/L de potassium au soluté dès que K < 5,5, contrôle toutes les heures.", "Quand la glycémie passe sous 14 mmol/L, continuez l'insuline et ajoutez du glucosé 10 % à 125 mL/h : la cible est la cétonémie, pas la glycémie."] },
  status_epilepticus: { title: 'État de mal épileptique', summary: "Homme de 34 ans (178 cm, 80 kg), épileptique, à court de traitement. Les secours l'amènent encore en crise : elle a commencé il y a environ 5 minutes. Pas encore de voie veineuse. Arrêtez la crise et protégez-le.", learning: ["Une crise qui dure 5 minutes est un état de mal : traitez, n'attendez pas.", "Première ligne : une benzodiazépine, midazolam 10 mg IM sans voie veineuse ou lorazépam 4 mg IV ; une seule répétition après 5-10 min si la crise continue.", "Les benzodiazépines marchent moins bien à mesure que la crise dure. À 20 minutes, deuxième ligne : lévétiracétam 60 mg/kg (max 4,5 g), fosphénytoïne ou valproate.", "Contrôlez la glycémie, donnez de l'oxygène, protégez les voies aériennes. Toujours en crise à 40 minutes : anesthésie et intubation (état de mal réfractaire)."] },
  copd_exacerbation: { title: 'Exacerbation de BPCO', summary: "Homme de 71 ans (172 cm, 68 kg), BPCO sévère, plus essoufflé depuis trois jours avec davantage d'expectorations. Il est assis, tire sur ses muscles du cou et il est somnolent. Donnez le bon oxygène, traitez l'obstruction et décidez de l'assistance ventilatoire.", learning: ["BPCO à risque de rétention de CO2 : visez une SpO2 de 88-92 % avec un masque Venturi 24-28 % ; l'oxygène à forte concentration fait monter la PaCO2 (moins de vasoconstriction hypoxique, effet Haldane, moins de commande hypoxique).", "Traitez l'obstruction : salbutamol nébulisé (avec ipratropium), prednisolone 30-40 mg, antibiotique si l'expectoration est purulente.", "Faites un gaz du sang tôt. Si pH < 7,35 et PaCO2 > 6,5 kPa (49 mmHg) persistent après le traitement médical, débutez une VNI à deux niveaux (IPAP 15 puis 20 et plus, EPAP 4-5) et recontrôlez le gaz dans les 1-2 h."] },
  svt: { title: 'Tachycardie à QRS fins', summary: "Femme de 32 ans (165 cm, 60 kg), cœur rapide et régulier depuis 40 minutes. Elle est anxieuse mais parle, pression 112/70. Faites le diagnostic et ramenez-la en rythme sinusal sans danger.", learning: ["Tachycardie régulière à QRS fins sans signe de gravité (choc, syncope, ischémie, insuffisance cardiaque) : manœuvres vagales d'abord. La manœuvre de Valsalva modifiée (effort 15 s puis allongée jambes levées) réussit environ 2,5 fois plus que la manœuvre classique.", "Puis adénosine 6 mg en bolus rapide avec rinçage dans une grosse veine, puis 12 mg, puis 18 mg. Prévenez la patiente : quelques secondes de gêne thoracique et une pause sur le scope.", "Cardioversion synchronisée seulement si elle devient instable ou si les médicaments échouent."] },
  hyperkalaemia: { title: 'Hyperkaliémie sévère', summary: "Homme de 64 ans (175 cm, 80 kg), insuffisant rénal chronique sous IEC, se sent faible. Sa kaliémie au gaz du sang est à 7,0 mmol/L. Protégez son cœur et faites baisser le potassium.", learning: ["K >= 6,5 est sévère : ECG 12 dérivations et scope. Ondes T pointues, ondes P aplaties et QRS qui s'élargit annoncent l'arrêt.", "Le calcium d'abord si l'ECG est anormal : il protège le cœur en quelques minutes mais ne baisse pas le potassium.", "Faites entrer le potassium dans les cellules : insuline 10 U avec 25 g de glucose (baisse d'environ 0,6-1 mmol/L en 30-60 min) et salbutamol nébulisé 10-20 mg. Puis éliminez-le (dialyse, chélateurs) et arrêtez la cause.", "L'insuline peut donner une hypoglycémie pendant des heures : contrôlez la glycémie régulièrement."] },
  hypoglycaemia: { title: 'Hypoglycémie', summary: "Femme de 68 ans (160 cm, 70 kg), diabétique de type 2, sous insuline lente depuis la semaine dernière. Sa fille l'a trouvée somnolente et en sueur ; ses propos sont incohérents. Trouvez la cause et traitez-la durablement.", learning: ["Tout patient somnolent, confus ou qui convulse : contrôlez la glycémie. L'hypoglycémie est < 4 mmol/L.", "Inconsciente ou incapable d'avaler : glucose IV 15-20 g (150-200 mL de G10 % ou 75-100 mL de G20 %), ou glucagon 1 mg IM sans voie veineuse. Recontrôlez après 10-15 min.", "Avec une insuline lente ou un sulfamide, elle récidive : débutez une perfusion de glucose et continuez les contrôles."] },
  mobitz_brady: { title: 'Bradycardie sur bloc de Mobitz II', summary: "Homme de 72 ans (176 cm, 78 kg), deux malaises ce matin. Pouls lent et pression basse. Analysez le rythme, traitez-le et protégez-le de l'asystolie.", learning: ["Bradycardie avec signes de gravité (choc, syncope, ischémie, insuffisance cardiaque) : atropine 500 µg IV, à répéter jusqu'à 3 mg.", "Mobitz II, bloc complet, pause récente > 3 s ou asystolie exposent à l'asystolie : mettez en place une mesure d'attente même si l'atropine aide (entraînement électrosystolique, isoprénaline 5 µg/min ou adrénaline 2-10 µg/min) et demandez une sonde d'entraînement endocavitaire.", "Dans le Mobitz II le bloc est sous-nodal : l'atropine change peu de chose."] },
  hyponatraemia: { title: 'Hyponatrémie sévère symptomatique', summary: "Femme de 72 ans (160 cm, 62 kg) sous diurétique thiazidique depuis trois semaines. Depuis hier elle vomit et elle est confuse ; elle est maintenant très somnolente. Trouvez la cause, traitez le danger et ne corrigez pas trop.", learning: ["Une hyponatrémie avec des symptômes sévères (vomissements, somnolence profonde, convulsions, coma) est une urgence quelle qu'en soit la cause : l'œdème cérébral tue.", "Donnez 150 mL de NaCl 3 % en 20 minutes, contrôlez la natrémie, et répétez jusqu'à deux fois jusqu'à une hausse de 5 mmol/L.", "Puis arrêtez : limitez la hausse à 10 mmol/L les premières 24 heures (8 ensuite). Une correction trop rapide expose à la myélinolyse osmotique.", "Arrêtez le thiazidique. Jamais de soluté hypotonique."] },
  pulmonary_oedema: { title: 'Œdème aigu du poumon', summary: "Homme de 74 ans (172 cm, 82 kg), insuffisant cardiaque, réveillé par une détresse respiratoire. Il est assis bien droit, gris et en sueur, avec une expectoration rose mousseuse et une pression à 190/115. Soulagez-le.", learning: ["OAP hypertensif : les poumons sont inondés car le cœur gauche ne peut pas se vider contre la postcharge. Asseyez le patient.", "CPAP ou VNI à deux niveaux tôt : elle rouvre les alvéoles inondées et diminue le travail respiratoire.", "Dérivé nitré IV si la systolique dépasse 110 mmHg (il baisse précharge et postcharge), et furosémide IV 40 mg (ou la dose habituelle).", "Pas de remplissage. Cherchez le facteur déclenchant : ischémie (ECG 12 dérivations), trouble du rythme, traitement non pris."] },
  hypertensive_emergency: { title: 'Urgence hypertensive', summary: "Homme de 58 ans (176 cm, 88 kg), a arrêté ses antihypertenseurs il y a un mois. Céphalée intense, vision floue, propos confus. Pression à 230/140. Faites-la baisser sans danger.", learning: ["Une urgence hypertensive est une pression très élevée AVEC une atteinte aiguë d'organe (cerveau, cœur, rein, rétine, aorte). Sans atteinte d'organe, ce n'est pas une urgence.", "Baissez la pression moyenne de 20-25 % sur les premières heures avec un médicament IV titrable (labétalol, urapidil, nicardipine) : le cerveau s'est adapté à la pression élevée et une baisse rapide provoque un AVC.", "Exceptions qui demandent une cible plus rapide et plus basse : dissection aortique, œdème aigu du poumon, prééclampsie.", "Surveillez la pression de façon invasive et répétez de petites doses."] },
  variceal_bleed: { title: 'Hémorragie par rupture de varices', summary: "Homme de 54 ans (178 cm, 80 kg), cirrhose alcoolique, vomit une grande quantité de sang rouge en salle d'attente. Il est pâle, en sueur et ictérique, l'abdomen distendu. Réanimez-le et arrêtez le saignement.", learning: ["Une hématémèse chez un cirrhotique est variqueuse jusqu'à preuve du contraire. Deux grosses voies veineuses, groupe et compatibilité.", "Débutez tout de suite un vasoactif, avant l'endoscopie (terlipressine 2 mg IV) : il baisse la pression portale. Antibioprophylaxie (ceftriaxone 1 g).", "Transfusez de façon restrictive jusqu'à une hémoglobine de 7-8 g/dL et ne remplissez pas trop : plus de volume, c'est plus de pression portale et plus de saignement.", "Ligature endoscopique dans les 12 heures, plus tôt s'il est instable ; protégez les voies aériennes s'il est somnolent ou vomit du sang. L'acide tranexamique n'aide pas."] },
  spinal_hypotension: { title: 'Hypotension après une rachianesthésie', summary: "Femme de 82 ans (155 cm, 52 kg), fracture du col du fémur, vient d'avoir une rachianesthésie avec 12,5 mg de bupivacaïne hyperbare 0,5 % pour une prothèse intermédiaire. Elle est scopée et perfusée. Prenez-la en charge pendant les 25 prochaines minutes.", learning: ["La rachianesthésie bloque le sympathique sous le niveau du bloc : artérioles et veines se dilatent. Plus le bloc est haut et la patiente âgée, plus la pression chute.", "Pour une fracture de hanche, petite dose (bupivacaïne hyperbare 10 mg ou moins) et pression à moins de 20 % de la valeur de base : traitez tôt par un vasopresseur (phényléphrine 50-100 µg, éphédrine 3-6 mg ou noradrénaline en perfusion) plutôt que par des litres de soluté.", "Un bloc à T4 ou au-dessus atteint les fibres cardio-accélératrices : le cœur ne peut pas accélérer et un retour veineux bas peut donner une bradycardie brutale. Éphédrine ou atropine, jambes surélevées.", "Les nausées après une rachianesthésie sont le plus souvent dues à l'hypotension : corrigez d'abord la pression."] },
  high_spinal: { title: 'Bloc trop étendu après une réinjection péridurale', summary: "Homme de 52 ans (178 cm, 85 kg) avec un cathéter péridural pour une prothèse de genou. Un collègue vient de réinjecter 15 mL de bupivacaïne 0,5 % sans dose test et a quitté la salle. Une minute plus tard il dit que ses mains fourmillent et qu'il respire mal. Prenez-le en charge.", learning: ["Mains qui fourmillent ou faibles, difficulté à respirer ou à parler et pression qui baisse peu après une dose péridurale : le bloc est trop haut. Un cathéter peut être ou migrer dans l'espace sous-arachnoïdien : aspirez toujours, faites une dose test et restez auprès du patient.", "Bloc étendu : appelez à l'aide, arrêtez la péridurale, oxygène, assistez la ventilation (ballon-masque puis intubation si le bloc atteint le diaphragme), vasopresseur et atropine ou adrénaline pour la bradycardie ; surélevez les jambes.", "Le patient peut être parfaitement conscient tout en étant incapable de respirer ou de bouger : parlez-lui, et sédatez une fois les voies aériennes sécurisées.", "Le bloc se lève en 1-2 heures : assistez-le jusque-là."] },
  pacu_ponv: { title: 'Salle de réveil : nausées, vomissements et frissons', summary: "Femme de 34 ans (165 cm, 62 kg), non fumeuse, a vomi après sa dernière opération ; elle arrive en salle de réveil après une cholécystectomie cœlioscopique. Elle a reçu 10 mg de morphine et aucun antiémétique. Elle est réveillée, froide et grelotte. Prenez-la en charge en salle de réveil.", learning: ["Score d'Apfel : femme, non fumeuse, antécédent de NVPO ou de mal des transports, opioïdes postopératoires. Quatre facteurs : environ 80 % de risque. Elle aurait dû recevoir deux ou trois antiémétiques en prophylaxie.", "Traitement de secours avec une classe non encore donnée (ondansétron 4 mg ou dropéridol 0,625-1,25 mg). La dexaméthasone met 1-2 heures à agir : c'est une prophylaxie, pas un secours.", "Frissons postopératoires : réchauffement actif (air pulsé), oxygène (ils augmentent la consommation d'oxygène), et péthidine 25 mg IV s'ils persistent.", "Sortie de salle de réveil seulement quand la température centrale est d'au moins 36,0 °C."] },
});
// The engine's refusals (patient.js, ett.js, infection.js) are English; in French they are shown translated.
const ERR_FR = {
  'patient in cardiac arrest': 'Patient en arrêt cardiaque', 'surgical airway in place': 'Abord trachéal chirurgical en place',
  'no pending order': 'Aucun ordre en attente', 'attempt in progress': 'Tentative en cours', 'unknown order': 'Ordre inconnu',
  'unknown drug': 'Médicament inconnu', 'unknown antibiotic': 'Antibiotique inconnu',
  'patient not relaxed: laryngospasm / bucking': 'Patient non curarisé : laryngospasme / toux sur la sonde',
  'pads first': "Posez d'abord les électrodes", 'not charged': 'Défibrillateur non chargé', 'no pads': 'Pas d\'électrodes posées',
  'no ward course in this case': "Pas de séjour en service dans ce cas", 'no tracheal tube': 'Pas de sonde trachéale',
  'no line to remove': 'Aucune ligne à retirer', 'no infusion for this drug': 'Pas de perfusion en cours pour ce médicament',
  'missing or non-numeric required parameter': 'Paramètre obligatoire manquant ou non numérique',
  'insert the bronchoscope first': "Introduisez d'abord le fibroscope", 'duplicate order id': "Numéro d'ordre déjà utilisé",
  'chest drain insertion in progress': 'Pose du drain thoracique en cours', 'busy with another airway procedure': 'Un autre geste sur les voies aériennes est en cours',
  'bronchoscopy needs a tracheal tube': 'La fibroscopie demande une sonde trachéale', 'airway already secured': 'Voies aériennes déjà sécurisées',
  'a spinal has already been given': 'La rachianesthésie a déjà été faite', 'a pneumothorax is already present': 'Un pneumothorax est déjà présent',
  'a drain is already in place on this side': 'Un drain est déjà en place de ce côté',
};
const ERR_FR_RE = [
  [/^parameter (\w+) must be a finite number$/, 'Le paramètre $1 doit être un nombre'],
  [/^(\S+) is not prescribed$/, "$1 n'est pas prescrit"], [/^(\S+) is already prescribed$/, '$1 est déjà prescrit'],
  [/^(\S+) has no (\w+) form here$/, "$1 n'existe pas en forme $2 ici"], [/^unknown event (.*)$/, 'Événement inconnu $1'],
  [/^amount must be more than 0 and at most (\S+) (\S+)$/, 'La dose doit être supérieure à 0 et au plus de $1 $2'],
  [/^rate must be in \[0, (\S+)\] (\S+)$/, 'Le débit doit être compris entre 0 et $1 $2'],
  [/^(\w+) must be in \[(\S+), (\S+)\]$/, 'La valeur $1 doit être comprise entre $2 et $3'],
];
/** An engine refusal in the current language (unknown messages are shown as they are). */
export function errText(msg) {
  if (lang !== 'fr' || typeof msg !== 'string') return msg;
  if (ERR_FR[msg]) return ERR_FR[msg];
  for (const [re, fr] of ERR_FR_RE) if (re.test(msg)) return msg.replace(re, fr);
  return msg;
}
